import{_ as o,o as n,c as a,aj as e}from"./chunks/framework.BwH0p-pt.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/introduction/introductions.md","filePath":"2.0/introduction/introductions.md","lastUpdated":1788942616000}'),r={name:"2.0/introduction/introductions.md"};function s(i,t,p,c,d,u){return n(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a> is an open-source Product Information Management (PIM) system built on the <strong>Laravel 12</strong> framework and requires <strong>PHP 8.3</strong>. It helps businesses organize, manage, and enrich their product information in one central repository.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p><strong>1) Centralized Product Management-</strong> Manage all your product data in one place with support for Simple and Configurable product types.</p><p><strong>2) Data Enrichment-</strong> Enhance your product information with detailed attributes, including support for 12 data types and swatch types for visual attribute options.</p><p><strong>3) Category Management-</strong> Organize products into categories for easier navigation, with customizable category fields.</p><p><strong>4) User Management-</strong> Control user access and permissions with role-based access control.</p><p><strong>5) API Integration-</strong> Seamlessly integrate with other systems via RESTful APIs with OAuth 2.0 authentication.</p><p><strong>6) Localization-</strong> Support for multiple languages and locales with automatic AI-powered translation.</p><p><strong>7) Import/Export Functionality-</strong> Easily import and export product data using CSV, XLS, and XLSX formats, with drag-and-drop file upload, real-time job tracking, and pause/resume/cancel controls.</p><p><strong>8) Magic AI for Product Content Generation-</strong> Automatically generate engaging product content using advanced LLM technology with support for 10+ AI providers including OpenAI, Gemini, Anthropic, Ollama, and Groq.</p><p><strong>9) Multi-Channel Support-</strong> Manage and distribute your product data across multiple sales channels from a single platform.</p><p><strong>10) AI Agent Chat-</strong> Interact with your PIM using natural language through the AI Agent Chat interface with 30+ built-in PIM tools for product management, data quality, and bulk operations.</p><p><strong>11) Product Completeness-</strong> Monitor data quality with product completeness scoring that tracks how much required information has been filled in per channel and locale.</p><p><strong>12) Notifications-</strong> Stay informed with in-app and email notifications for import/export jobs, product changes, and system events.</p><p><strong>13) Webhooks-</strong> Automate workflows with product update webhooks that trigger HTTP callbacks when product data changes.</p><p><strong>14) Enhanced Dashboard-</strong> Get a comprehensive overview of your catalog with widgets for product statistics, activity charts, completeness scores, channel readiness, and recent operations.</p><p><strong>15) Product Bulk Edit-</strong> Edit multiple products at once by selecting them from the datagrid and applying bulk changes to shared attributes.</p><p><strong>16) PostgreSQL Support-</strong> Full support for PostgreSQL databases in addition to MySQL for improved cross-database compatibility.</p>',19)])])}const h=o(r,[["render",s]]);export{g as __pageData,h as default};
